#!/usr/bin/env node
/**
 * Auto-heal Open Graph tags on prerendered HTML pages.
 *
 * Some legacy HTML pages in /public were generated by older scripts that
 * never emitted og:image, og:image:width/height/alt, or twitter:image. Until
 * every legacy page is regenerated through the canonical generator, this
 * patcher injects the missing tags in-place so social previews work and the
 * SEO meta audit (`scripts/check-seo-meta.mjs`) passes in CI.
 *
 * Idempotent: pages that already contain og:image are left untouched.
 *
 * Wired into `npm run build` between the generators and the audit.
 */

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const ROOT = resolve(__dirname, "..");
const PUBLIC_DIR = join(ROOT, "public");

const SITE_URL = "https://rehablookup.com";
const OG_IMAGE = `${SITE_URL}/og-image.jpg`;

// Pages we never touch (handled separately or noindex by design).
const SKIP = new Set(["index.html", "404.html"]);

function getMeta(html, attr, name) {
  const re = new RegExp(
    `<meta[^>]*\\b${attr}=["']${name}["'][^>]*\\bcontent=["']([^"']*)["'][^>]*>`,
    "i",
  );
  const m = html.match(re);
  return m ? m[1] : null;
}

function patchHtml(html) {
  // Already has og:image? Skip.
  if (/property=["']og:image["']/i.test(html)) return null;

  const ogTitle =
    getMeta(html, "property", "og:title") ||
    getMeta(html, "name", "twitter:title") ||
    (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? "RehabLookup");

  const safeTitle = ogTitle.replace(/"/g, "&quot;");

  const injection = [
    `<meta property="og:image" content="${OG_IMAGE}">`,
    `<meta property="og:image:width" content="1200">`,
    `<meta property="og:image:height" content="630">`,
    `<meta property="og:image:alt" content="${safeTitle}">`,
  ];

  // Also add twitter:image if missing — Twitter falls back to og:image but
  // having an explicit tag avoids edge cases with summary_large_image cards.
  if (!/name=["']twitter:image["']/i.test(html)) {
    injection.push(`<meta name="twitter:image" content="${OG_IMAGE}">`);
  }

  // Inject right after og:url if present, otherwise after the first og:* tag,
  // otherwise just before </head>.
  const tags = injection.join("\n  ");

  const ogUrlMatch = html.match(/<meta[^>]*\bproperty=["']og:url["'][^>]*>/i);
  if (ogUrlMatch) {
    return html.replace(ogUrlMatch[0], `${ogUrlMatch[0]}\n  ${tags}`);
  }
  const ogAnyMatch = html.match(/<meta[^>]*\bproperty=["']og:[^"']+["'][^>]*>/i);
  if (ogAnyMatch) {
    return html.replace(ogAnyMatch[0], `${ogAnyMatch[0]}\n  ${tags}`);
  }
  return html.replace(/<\/head>/i, `  ${tags}\n</head>`);
}

const files = readdirSync(PUBLIC_DIR)
  .filter((f) => f.endsWith(".html") && !SKIP.has(f))
  .sort();

let patched = 0;
let skipped = 0;

for (const f of files) {
  const fullPath = join(PUBLIC_DIR, f);
  const html = readFileSync(fullPath, "utf8");
  const next = patchHtml(html);
  if (next === null) {
    skipped++;
    continue;
  }
  writeFileSync(fullPath, next, "utf8");
  patched++;
}

console.log(`[patch-og-image] Patched ${patched} legacy page(s); ${skipped} already had og:image.`);
